CREATE TABLE IF NOT EXISTS games (id TEXT PRIMARY KEY, level TEXT NOT NULL, seed INTEGER NOT NULL, created_at INTEGER NOT NULL, used INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS players (key TEXT PRIMARY KEY, display TEXT NOT NULL, token_hash TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS bests (player_key TEXT NOT NULL, level TEXT NOT NULL, noflag INTEGER NOT NULL, time_ms INTEGER NOT NULL, game_id TEXT NOT NULL, updated_at INTEGER NOT NULL, PRIMARY KEY (player_key, level, noflag));
CREATE INDEX IF NOT EXISTS bests_board ON bests (level, noflag, time_ms);
CREATE TABLE IF NOT EXISTS hits (key TEXT NOT NULL, bucket TEXT NOT NULL, minute INTEGER NOT NULL, count INTEGER NOT NULL, PRIMARY KEY (key, bucket, minute));
